function sumIndicesWithKSetBits(nums, k) {
  let total = 0;
  for (let i = 0; i < nums.length; i++) {
    let bits = 0;
    let rest = i;
    while (rest > 0) {
      rest &= rest - 1;
      bits++;
    }
    if (bits === k) {
      total += nums[i];
    }
  }
  return total;
}

