function generate(rand, size) {
  if (size === 'large') {
    const nums = Array.from({ length: 1000 }, () => 1 + Math.floor(rand() * 100000));
    return [nums, Math.floor(rand() * 8)];
  }
  const n = 1 + Math.floor(rand() * 16);
  const top = rand() < 0.5 ? 10 : 100000;
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  return [nums, Math.floor(rand() * 5)];
}
